using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _gateway = new PaymentGateway();
    }

    // ───────────────────────────────────────────────
    //  ChargeAsync – happy path
    // ───────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccessResult()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 49.99m);

        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCharge_ReturnsNonEmptyChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 100m);

        Assert.IsTrue(result.Success);
        Assert.AreNotEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(1.00)]
    [DataRow(9999.99)]
    public async Task ChargeAsync_VariousValidAmounts_Succeeds(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    // ───────────────────────────────────────────────
    //  ChargeAsync – validation / edge cases
    // ───────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("tok_valid", 0m));
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("tok_valid", -10m));
    }

    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.ChargeAsync(null!, 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyCardToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(string.Empty, 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_WhitespaceCardToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("   ", 10m));
    }

    // ───────────────────────────────────────────────
    //  ChargeAsync – uniqueness
    // ───────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_TwoCharges_ReturnDifferentChargeIds()
    {
        var first = await _gateway.ChargeAsync("tok_a", 10m);
        var second = await _gateway.ChargeAsync("tok_b", 20m);

        Assert.AreNotEqual(first.ChargeId, second.ChargeId);
    }

    // ───────────────────────────────────────────────
    //  RefundAsync – happy path
    // ───────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 50m);
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsNotNull(refund);
        Assert.IsTrue(refund.Success);
        Assert.IsNotNull(refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsNonEmptyRefundId()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 25m);
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.AreNotEqual(string.Empty, refund.RefundId);
    }

    // ───────────────────────────────────────────────
    //  RefundAsync – validation / edge cases
    // ───────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(string.Empty));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailure()
    {
        var refund = await _gateway.RefundAsync("chg_does_not_exist");

        Assert.IsFalse(refund.Success);
    }

    // ───────────────────────────────────────────────
    //  RefundAsync – duplicate refund
    // ───────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_SameChargeIdTwice_SecondRefundFails()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 75m);

        var first = await _gateway.RefundAsync(charge.ChargeId);
        var second = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(first.Success);
        Assert.IsFalse(second.Success);
    }

    // ───────────────────────────────────────────────
    //  Record equality sanity checks
    // ───────────────────────────────────────────────

    [TestMethod]
    public void ChargeResult_EqualValues_AreEqual()
    {
        var a = new ChargeResult("chg_123", true);
        var b = new ChargeResult("chg_123", true);

        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_DifferentIds_AreNotEqual()
    {
        var a = new RefundResult("ref_1", true);
        var b = new RefundResult("ref_2", true);

        Assert.AreNotEqual(a, b);
    }
}

